    public static class TadeuszRóżewicz
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "To są nazwy puste i jednoznaczne: człowiek i zwierzę miłość i nienawiść wróg i przyjaciel ciemność i światło.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Człowieka tak się zabija jak zwierzę widziałem: furgony porąbanych ludzi którzy nie zostaną zbawieni.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Szukam nauczyciela i mistrza niech przywróci mi wzrok słuch i mowę niech jeszcze raz nazwie rzeczy i pojęcia niech oddzieli światło od ciemności.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Zaraz zrobimy kawę. Wprawdzie nie mam kawy, filiżanek i pieniędzy, ale od czego jest nadrealizm, metafizyka, poetyka snów.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Oczy matki wszystko widzące patrzą na urodziny patrzą przez całe życie i patrzą po śmierci z „tamtego świata”.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Polityka zmieni się w kicz, miłość w pornografię, muzyka w hałas, sport w prostytucję, religia w naukę, nauka w wiarę.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Mam lat dwadzieścia Jestem mordercą Jestem narzędziem Tak ślepym jak miecz W dłoni kata", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nie wierzę w przemianę wody w wino Nie wierzę w grzechów odpuszczenie Nie wierzę w ciała zmartwychwstanie", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Zamordowałem człowieka I czerwonymi palcami Gładziłem białe piersi kobiet.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Zwracam się do was kapłani nauczyciele sędziowie artyści szewcy lekarze referenci i do ciebie mój ojcze Wysłuchajcie mnie.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "my zazdrościliśmy roślinom i kamieniom zazdrościliśmy psom chciałbym być szczurem mówiłem wtedy do niej chciałabym nie być chciałabym zasnąć", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "zapomnijcie o nas nie pytajcie o naszą młodość zostawcie nas", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Ale kto zobaczy moją matkę w sinym kitlu w białym szpitalu która trzęsie się która sztywnieje z drewnianym uśmiechem z białymi dziąsłami Która wierzyła przez pięćdziesiąt lat a teraz płacze i mówi: „nie wiem… nie wiem”.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "a ty kiedy patrzysz na siebie co widzisz widzę człowieka stworzonego na obraz i podobieństwo boga który odszedł", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "biel najlepiej opisać szarością", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Byli szczęśliwi dawniejsi poeci pod liściem dębu śpiewali jak dzieci A nasze drzewo w nocy zaskrzypiało I zwisło na nim pogardzone ciało.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Czy można pisać o miłości słysząc krzyki zamordowanych i pohańbionych czy można pisać o śmierci patrząc na twarzyczki dzieci.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Dniu mój brylancie najpiękniejszy w świecie domie złoty błękitny wielorybie łzo w moich oczach.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Dopóki nie poczujesz się nieszczęśliwy, nie narodzi się w tobie „poezja”!", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Doprawdy nie mam czasu na skończenie tego wiersza kto ma teraz czas na pisanie wierszy", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Dzieciństwo jest jak zatarte oblicze na złotej monecie która dźwięczy czysto.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Jak my się kaleczymy roztargnieni spieszący się jak my się kaleczymy wzajemnie okrutni w skupieniu czujni nieomylni w zadawaniu ciosu.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Jak dobrze Jestem z tobą tak mi serce bije myślałem człowiek nie ma serca.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Jesteś koroną drzewa które rośnie we mnie od rana do nocy.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Kaliban niewolnik nauczony ludzkiej mowy czeka z pyskiem w gnoju z nogami w raju obwąchuje człowieka czeka.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "każdy miał swojego Żyda albo księdza w każdym siedzi ksiądz Robak Jankiel i Konrad Wallenrod", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Leżałem w ubraniu na łóżku i myślałem o tym, że stoją tu różne meble, leżą książki, wiszą obrazy, ale to wszystko nie ma sensu. Ja też tu leżę i tez nie mam sensu.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Leżę na starym tapczanie ze sprężyną w boku nade mną ktoś wali młotem pode mną ktoś wali młotem", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Lubię stare kobiety brzydkie kobiety złe kobiety są solą ziemi", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Moja miła ma oczy które opadają na mnie jak jesienny szary deszcz.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Mój język chce wejść w usta dojrzałej dziewczyny.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Na piaskach moich snów ktoś nakreślił znak ryby i odszedł.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "na prześcieradłach krew wizerunek miłości", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nagle otworzy się okno i matka zawoła już czas wracać.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "na kołkach zwykła deska,na desce dwie litery, tu się zaczyna groteska: bo to nie nasze litery, deska od trumny wyrwana, ja serca nie mam wcale, tu w boku zwykła rana.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nasza mała stabilizacja.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nic mi nie jest dajcie mi spokój. Z głową w dłoniach tak siedzę i siedzę. Jakże im opowiem o tej długiej i splątanej drodze.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nic nadchodzi nic w czarodziejskim płaszczu Prospera nic z ulic i ust z ambon i wież nic z głośników mówi do niczego o niczym nic płodzi nic nic wychowuje nic nic czeka na nic nic grozi nic skazuje nic ułaskawia.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Nie patrzcie wilkiem Na człowieka Który pyta o wolne miejsce W przedziale kolejowym Zrozumcie Inni ludzie też mają Dwie nogi i siedzenie.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Od kilku lat proces umierania poezji jest przyspieszony.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Odwróciła twarz od ściany przecież mnie kocha dlaczego odwróciła się ode mnie więc takim ruchem głowy można odwrócić się od świata na którym ćwierkają wróble i młodzi ludzie chodzą w krzyczących krawatach Ona jest teraz sama w obliczu martwej ściany i tak już zostanie.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "pisałem już bardzo długo nagle spostrzegłem że nie mam w ręku pióra", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Poetą jest ten który pisze wiersze I ten który wierszy nie pisze", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Poezja współczesna to walka o oddech.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Pomnik Kafki stanął w Pradze oczywiście sam nie stanął postawiono go nie pytając czy ma chęć stać w tym miejscu", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Rozstępują się straszliwe ciemności nagromadzone nad światem przez złych ludzi kiedy w sercu małego chłopca świeci iskierka miłości.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Ukołysany między morzem i białymi jak noc udami dziewczyny.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Widzę szalonych którzy chodzili po morzu wierzyli do końca i poszli na dno.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Więc to był jeden dzień z tych najcenniejszych dni które nigdy nie wracają.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Znów się udała ta sztuczka naszej starej ludzkości.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "życie bez boga jest możliwe życie bez boga jest niemożliwe", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Od stuleci na każdej wojnie gwałci się kobiety. To nawet przyjemne zajęcie, sam też bym czasem zgwałcił, jakbym dogonił. Ale noga mnie boli, kolano.", Author = "Tadeusz Różewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Tadeusz_Różewicz", Text = "Seks jest jedną z najpotężniejszych religii współczesności. Nie waham się stwierdzić, że ma największą ilość wyznawców i to wyznawców praktykujących… Seks ma na swoje usługi cały świat.", Author = "Tadeusz Różewicz" },
        };
    }
